    'siteAvail.doc1': '① 站点主数据：本地 db/app.db → master_site_db（805 站）。使用字段：site_id、site_name、region、province_county、network_type、fme_name、supervisor、vip_site、site_type。行按 Supervisor / FME 过滤。',
    'siteAvail.doc2': '② 可用率取数（站点级天粒度，四种制式）：G(2G)：远端 db.sqlite3 → 2G_Main_Kpi_Site_Daily，字段 306004:TCH in service rate(%)（UME 官方原值）；U(3G)：远端 db.sqlite3 → 3G_Main_Kpi_Site_Daily，字段 300857:Cell Validity Rate(%)（UME 官方原值）；L(4G)：远端 db.sqlite3 → 4G_Main_Kpi_Site_Daily，字段 1638004469345:[FDD]Cell Availability[SDR_ITBBU]（UME 官方原值）；TDD(Tdd)：本地 ran_kpi_avalability_1day.sqlite3 → Daily_KPI_RPA_CELL_AVAIL_TDD，派生口径 AVG(Cell Service Time(s)) / 86400（站点当天各 TDD 小区服务时长折算的算术平均）。',
    'siteAvail.doc3': '③ 统计口径：日值 = UME 站点级原值（TDD 为派生折算）；周均 = 该自然周（周一起算，首尾周裁剪到本月）内有值日期的算术平均；月均 = 本月内有值日期的算术平均（空值天不参与，不补零）；未达标 = 日值 < 阈值（默认 99.65%，可调）。四制式月均恒显示，周/天明细列随顶部制式切换。',
    'siteAvail.doc4': '④ 工单（单子）：本地 db/app.db → eflow_tt，按 created_time 落在统计月内 [月初 00:00:00，月末 23:59:59] 归属；未闭环 = status ≠ \'Closed\'；每条 TT 按 site_id 精确匹配（未命中则站点名规范化匹配）唯一归属到一个站点，不重复计数。',
    'siteAvail.doc5': '⑤ 查询条件与时间范围：月份（YYYY-MM，默认当前月，可选最近 12 个月）+ Supervisor + FME + 仅看有数据站点；周/天切换与制式切换为展示维度，不重新查询。后端缓存 5 分钟。',
