    'siteAvail.doc1': '① Site master data: local db/app.db → master_site_db (805 sites). Fields: site_id, site_name, region, province_county, network_type, fme_name, supervisor, vip_site, site_type. Rows filtered by Supervisor / FME.',
    'siteAvail.doc2': '② Availability sources (site-level daily, four techs) — G (2G): remote db.sqlite3 → 2G_Main_Kpi_Site_Daily, field 306004:TCH in service rate(%) (official UME value); U (3G): remote db.sqlite3 → 3G_Main_Kpi_Site_Daily, field 300857:Cell Validity Rate(%) (official UME value); L (4G): remote db.sqlite3 → 4G_Main_Kpi_Site_Daily, field 1638004469345:[FDD]Cell Availability[SDR_ITBBU] (official UME value); TDD (Tdd): local ran_kpi_avalability_1day.sqlite3 → Daily_KPI_RPA_CELL_AVAIL_TDD, derived as AVG(Cell Service Time(s)) / 86400 (arithmetic mean over the TDD cells of the site per day).',
    'siteAvail.doc3': '③ Aggregation: daily = UME site-level raw value (TDD derived); weekly avg = arithmetic mean of valued days within the calendar week (weeks start Monday, edge weeks clipped to the month); monthly avg = arithmetic mean of valued days in the month (null days excluded, not zero-filled); below threshold = daily value < threshold (default 99.65%, adjustable). Monthly averages of all four techs are always shown; weekly/daily detail columns follow the tech switch.',
    'siteAvail.doc4': "④ Tickets: local db/app.db → eflow_tt, attributed by created_time within the month [first day 00:00:00, last day 23:59:59]; open = status ≠ 'Closed'; each TT is uniquely attributed to one site via exact site_id match (fallback: normalized site-name match), never double-counted.",
    'siteAvail.doc5': '⑤ Query conditions & time range: month (YYYY-MM, default current month, last 12 months selectable) + Supervisor + FME + only-sites-with-data trigger backend queries; tech / weekly-daily / threshold switches are display-only and do not re-query. Backend cache: 5 minutes.',
