    // Packet Loss metric explanations
    'pl.explain.totalSites': 'Total sites monitored for packet loss.\nSource: Packet Loss Status Report site master data (lte_pl.sqlite3, last 7 complete calendar days, hourly granularity; the unfinished current day is excluded).',
    'pl.explain.critical': 'Sites whose FINAL_STATUS is Critical.\nCalculation: STATUS is derived from the 0-23 flag block (a flag = 1 when the same hour exceeds 0.5% PL in each of the last 3 days; all-zero flags = OK). STATUS≠OK and Last 1 day Max PL ≥ 5% = Critical.\nLast 1 day Max PL = max hourly PL of the latest complete day (00-23h).',
    'pl.explain.major': 'Sites whose FINAL_STATUS is Major.\nCalculation: STATUS≠OK and Last 1 day Max PL in [1%, 5%) = Major.',
    'pl.explain.minor': 'Sites whose FINAL_STATUS is Minor.\nCalculation: STATUS≠OK and Last 1 day Max PL in [0.5%, 1%) = Minor.',
    'pl.explain.warning': 'Sites whose FINAL_STATUS is Warning.\nCalculation: STATUS≠OK and Last 1 day Max PL in [0.1%, 0.5%) = Warning.',
    'pl.explain.noPacketLoss': 'Sites considered normal.\nCalculation: STATUS=OK (all 0-23 flags are 0, i.e. no hour exceeded 0.5% PL in each of the last 3 days) is forced to No Packet loss; or STATUS≠OK but Last 1 day Max PL < 0.1%.',
    'pl.explain.affectedSites': 'Affected Sites = Critical + Major (STATUS≠OK and Last 1 day Max PL ≥ 1%).\nMatches the "Affected Sites (Critical+Major)" row in the Excel report Summary sheet; Minor/Warning are not included.',
    'pl.explain.granularity': 'Data granularity: last 7 complete calendar days, hourly (SDR + IPRAN IPPD packet loss rate); the unfinished current day is excluded.\nSTATUS rule: an hour is flagged 1 when its PL exceeds 0.5% in each of the last 3 days at the same hour; all-zero flags -> OK, otherwise NOK.\nSDR = Software Defined Radio (3G/2G); IPRAN = IP backhaul transport network.',

